def transform(grid):
    # Fill missing cells by extending the repeating diagonal pattern when
    # each diagonal is determined by observed cells. Fall back to row-period
    # completion for grids with repeated full rows.
    h, w = len(grid), len(grid[0])
    if h == w:
        diag = {}
        consistent = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = (c-r) % w
                    if k in diag and diag[k] != v:
                        consistent = False
                    diag[k] = v
        if consistent and len(diag) == w:
            return [[diag[(c-r) % w] for c in range(w)] for r in range(h)]
    # Find the shortest row period compatible with every nonblank row.
    for p in range(1, h + 1):
        ok = True
        for r in range(h):
            for s in range(h):
                if (r-s) % p == 0:
                    for c in range(w):
                        if grid[r][c] and grid[s][c] and grid[r][c] != grid[s][c]:
                            ok = False
        if ok:
            # Copy any observed row from its congruence class.
            out = [row[:] for row in grid]
            for r in range(h):
                if not any(out[r]):
                    for s in range(h):
                        if (r-s) % p == 0 and any(grid[s]):
                            out[r] = grid[s][:]
                            break
            return out
    return [row[:] for row in grid]
